-- ===== 20261006023104_session_schedule_import.sql (sha256 3cb92e738cc0196c6e2166665ffc179a61ddf462edf5ebcde848b6f3b03863cc) =====
-- Conference schedule import (Claude-owned).
-- CODEX REVIEW REQUIRED: adds the nullable column public.sessions."endsAt" (core table).
-- It also adds the sessionImport handler to Claude's own extension dispatcher.
-- Nothing else in the core changes: conference_snapshot already serializes every session column,
-- so "endsAt" appears in snapshots automatically; existing session commands leave it null.

alter table public.sessions add column "endsAt" timestamptz;
alter table public.sessions add constraint sessions_ends_after_start check ("endsAt" is null or "endsAt" > "startsAt");
create index sessions_committee_start on public.sessions(committee_id, "startsAt");

-- Handlers run inside private.apply_operations_mutation (SECURITY DEFINER) and are not callable directly.
-- Bulk session creation. Row n gets id substr(mutation,1,24)||hex(n), matching the client's optimistic ids.
-- A session that already exists for the same committee and start time is skipped (safe re-import).
create function private.ops_session_import(conf uuid, mutation uuid, command jsonb) returns uuid[]
language plpgsql set search_path='' as $$
declare r jsonb; n integer := 0; cid uuid; starts timestamptz; ends timestamptz; session_name text; affected uuid[] := '{}';
begin
 if jsonb_typeof(command->'rows') is distinct from 'array' or jsonb_array_length(command->'rows') not between 1 and 500 then
   raise exception 'Import between 1 and 500 sessions at a time' using errcode='22023';
 end if;
 for r in select value from jsonb_array_elements(command->'rows') loop
   n := n + 1;
   cid := private.uuid_or_null(r->>'committeeId');
   session_name := trim(r->>'name');
   starts := (r->>'startsAt')::timestamptz;
   ends := nullif(r->>'endsAt','')::timestamptz;
   if cid is null or not exists(select 1 from public.committees where id = cid and conference_id = conf) then raise exception 'Committee unavailable' using errcode='22023'; end if;
   if session_name is null or length(session_name) not between 1 and 120 then raise exception 'Session name required' using errcode='22023'; end if;
   if starts is null or (ends is not null and ends <= starts) then raise exception 'Session times invalid' using errcode='22023'; end if;
   continue when exists(select 1 from public.sessions where committee_id = cid and "startsAt" = starts);
   insert into public.sessions(id, conference_id, committee_id, name, "startsAt", "endsAt", state)
   values ((substr(mutation::text,1,24)||lpad(to_hex(n),12,'0'))::uuid, conf, cid, session_name, starts, ends, 'scheduled');
   if not cid = any(affected) then affected := affected || cid; end if;
 end loop;
 return affected;
end; $$;
revoke all on function private.ops_session_import(uuid,uuid,jsonb) from public, anon, authenticated;

-- Dispatcher: shared authorization, idempotency, locking, audit and notification for every extension command.
create or replace function private.apply_operations_mutation(conf uuid, mutation uuid, command jsonb, requested_role public.conference_role, expected text, client_time timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor uuid := auth.uid(); kind text := command->>'type'; cid uuid; entity uuid; affected uuid[] := '{}'; c uuid; topic text := 'configuration';
 allowed public.conference_role[] := array['admin']::public.conference_role[];
 prior private.mutation_receipts;
 new_id uuid := (substr(mutation::text,1,24)||'000000000001')::uuid;
 payload jsonb := jsonb_build_object('command',command,'role',requested_role,'expected',expected,'client_time',client_time);
begin
 if actor is null then raise exception 'Session required' using errcode='42501'; end if;
 if pg_column_size(command) > 262144 then raise exception 'Command too large' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(mutation::text,0));
 select * into prior from private.mutation_receipts where id = mutation;
 if found then
   if prior.actor_id <> actor or prior.conference_id <> conf or prior.payload <> payload then raise exception 'Idempotency key reused for a different action' using errcode='22023'; end if;
   return;
 end if;
 case kind
 when 'submissionLink' then
   cid := private.uuid_or_null(command->>'committeeId');
   if cid is null or not exists(select 1 from public.committees where id = cid and conference_id = conf) then raise exception 'Committee unavailable' using errcode='22023'; end if;
 when 'resolutionLink' then
   select committee_id into cid from public.documents where id = private.uuid_or_null(command->>'documentId') and conference_id = conf;
   if cid is null then raise exception 'Document unavailable' using errcode='42501'; end if;
   allowed := array['chair','admin']::public.conference_role[]; topic := 'documents';
 when 'sessionImport' then cid := null;
 else raise exception 'Unknown operations command' using errcode='22023';
 end case;
 if not requested_role = any(allowed) then raise exception '% access required', case when 'chair' = any(allowed) then 'Chair' else 'Executive' end using errcode='42501'; end if;
 if not private.has_access(conf, cid, array[requested_role]) then raise exception 'This session has no access to this role or committee' using errcode='42501'; end if;
 if cid is not null then perform 1 from public.committees where id = cid and conference_id = conf for update;
 else perform 1 from public.conferences where id = conf for update; end if;
 case kind
 when 'submissionLink' then entity := private.ops_submission_link(conf, cid, actor, new_id, command);
 when 'resolutionLink' then entity := private.ops_resolution_link(conf, cid, command);
 when 'sessionImport' then affected := private.ops_session_import(conf, mutation, command);
 end case;
 insert into public.audit_log(conference_id, committee_id, "actorId", action, "entityId", mutation_id, details)
 values (conf, cid, actor, kind || ' ' || coalesce(command->>'action', 'updated'), coalesce(entity, cid, conf), mutation,
   case kind when 'submissionLink' then command - 'token' when 'sessionImport' then jsonb_build_object('type', kind, 'rows', jsonb_array_length(command->'rows')) else command end);
 insert into private.mutation_receipts(id, conference_id, actor_id, payload) values (mutation, conf, actor, payload);
 insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, cid, topic, mutation);
 -- Chairs subscribe per committee: notify each affected committee as well (one small row each).
 foreach c in array affected loop
   insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, c, 'configuration', gen_random_uuid());
 end loop;
end; $$;
insert into supabase_migrations.schema_migrations(version,name,statements) values('20261006023104','session_schedule_import',array[$ledger$-- applied from supabase/migrations/20261006023104_session_schedule_import.sql (sha256 3cb92e738cc0196c6e2166665ffc179a61ddf462edf5ebcde848b6f3b03863cc)$ledger$]);

-- ===== 20261006023106_photo_schedule.sql (sha256 76a81cef42a0c54c8f6ee55844584563c5f14c3b4d7d9863df14a08fd0a7c2b5) =====
-- School group-photo schedule and chair reminders (Claude-owned). Additive only.
-- Reminders are derived on each device from these authoritative timestamps; Realtime only speeds up refresh.
-- CODEX REVIEW REQUIRED only for the shared pattern (new tables readable by staff); no core table changes.

create table public.photo_slots (
 id uuid primary key default gen_random_uuid(), conference_id uuid not null references public.conferences(id),
 school_id uuid not null,
 starts_at timestamptz not null, ends_at timestamptz,
 location text not null check (length(trim(location)) between 1 and 120),
 note text not null default '' check (length(note) <= 300),
 enabled boolean not null default true,
 warn_minutes integer not null default 10 check (warn_minutes between 1 and 60),
 revision bigint not null default 1,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 check (ends_at is null or ends_at > starts_at),
 unique (id, conference_id),
 foreign key (school_id, conference_id) references public.schools(id, conference_id)
);
create index photo_slots_conference_start on public.photo_slots(conference_id, starts_at);
create index photo_slots_school on public.photo_slots(school_id);
alter table public.photo_slots enable row level security;
revoke all on public.photo_slots from anon, authenticated;
grant select on public.photo_slots to authenticated;
create policy read_authorized on public.photo_slots for select to authenticated
 using (private.has_access(conference_id, null, array['admin','chair','approval','logistics','observer']::public.conference_role[])
        or exists(select 1 from public.user_access a where a.user_id = (select auth.uid()) and a.conference_id = photo_slots.conference_id and a.role = 'chair' and a.revoked_at is null and a.expires_at > now()));

-- One row per committee, slot, stage ("warning" / "due") and slot revision. A rescheduled slot has a new
-- revision, so earlier acknowledgements no longer count and the reminder appears again.
create table public.photo_acknowledgements (
 id uuid primary key default gen_random_uuid(), conference_id uuid not null references public.conferences(id),
 committee_id uuid not null, slot_id uuid not null,
 stage text not null check (stage in ('warning','due')), slot_revision bigint not null,
 actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique (slot_id, committee_id, stage, slot_revision),
 foreign key (committee_id, conference_id) references public.committees(id, conference_id),
 foreign key (slot_id, conference_id) references public.photo_slots(id, conference_id)
);
create index photo_acknowledgements_conference on public.photo_acknowledgements(conference_id);
create index photo_acknowledgements_committee on public.photo_acknowledgements(committee_id);
alter table public.photo_acknowledgements enable row level security;
revoke all on public.photo_acknowledgements from anon, authenticated;
grant select on public.photo_acknowledgements to authenticated;
create policy read_authorized on public.photo_acknowledgements for select to authenticated
 using (private.has_access(conference_id, committee_id, array['admin','chair','observer']::public.conference_role[]));

-- Committees with at least one delegate from the given schools (for targeted notifications).
create function private.committees_for_schools(schools uuid[]) returns uuid[] language sql stable set search_path='' as $$
 select coalesce(array_agg(distinct committee_id), '{}') from public.delegates where "schoolId" = any(schools);
$$;
revoke all on function private.committees_for_schools(uuid[]) from public, anon, authenticated;

create function private.ops_photo_slot(conf uuid, new_id uuid, command jsonb) returns uuid[]
language plpgsql set search_path='' as $$
declare slot_id uuid := private.uuid_or_null(command->>'slotId'); school uuid := private.uuid_or_null(command->>'schoolId'); old_school uuid;
begin
 if school is null or not exists(select 1 from public.schools where id = school and conference_id = conf) then raise exception 'School unavailable' using errcode='22023'; end if;
 if command->>'action' = 'create' then
   insert into public.photo_slots(id, conference_id, school_id, starts_at, ends_at, location, note, enabled, warn_minutes)
   values (new_id, conf, school, (command->>'startsAt')::timestamptz, nullif(command->>'endsAt','')::timestamptz, trim(command->>'location'),
           coalesce(command->>'note',''), coalesce((command->>'enabled')::boolean, true), coalesce((command->>'warnMinutes')::integer, 10));
   return private.committees_for_schools(array[school]);
 elsif command->>'action' = 'update' then
   select school_id into old_school from public.photo_slots where id = slot_id and conference_id = conf for update;
   if old_school is null then raise exception 'Photo slot unavailable' using errcode='22023'; end if;
   update public.photo_slots set school_id = school, starts_at = (command->>'startsAt')::timestamptz, ends_at = nullif(command->>'endsAt','')::timestamptz,
     location = trim(command->>'location'), note = coalesce(command->>'note',''), enabled = coalesce((command->>'enabled')::boolean, true),
     warn_minutes = coalesce((command->>'warnMinutes')::integer, 10), revision = revision + 1, updated_at = now()
   where id = slot_id;
   return private.committees_for_schools(array[school, old_school]);
 end if;
 raise exception 'Unknown photo action' using errcode='22023';
end; $$;
revoke all on function private.ops_photo_slot(uuid,uuid,jsonb) from public, anon, authenticated;

-- Bulk import. A slot for the same school and start time is skipped. Row n gets id prefix||hex(n).
create function private.ops_photo_import(conf uuid, mutation uuid, command jsonb) returns uuid[]
language plpgsql set search_path='' as $$
declare r jsonb; n integer := 0; school uuid; starts timestamptz; schools uuid[] := '{}';
begin
 if jsonb_typeof(command->'rows') is distinct from 'array' or jsonb_array_length(command->'rows') not between 1 and 300 then raise exception 'Import between 1 and 300 photo slots at a time' using errcode='22023'; end if;
 for r in select value from jsonb_array_elements(command->'rows') loop
   n := n + 1;
   school := private.uuid_or_null(r->>'schoolId'); starts := (r->>'startsAt')::timestamptz;
   if school is null or not exists(select 1 from public.schools where id = school and conference_id = conf) then raise exception 'School unavailable' using errcode='22023'; end if;
   continue when exists(select 1 from public.photo_slots where school_id = school and starts_at = starts);
   insert into public.photo_slots(id, conference_id, school_id, starts_at, ends_at, location, note, warn_minutes)
   values ((substr(mutation::text,1,24)||lpad(to_hex(n),12,'0'))::uuid, conf, school, starts, nullif(r->>'endsAt','')::timestamptz, trim(r->>'location'),
           coalesce(r->>'note',''), coalesce((r->>'warnMinutes')::integer, 10));
   schools := schools || school;
 end loop;
 return private.committees_for_schools(schools);
end; $$;
revoke all on function private.ops_photo_import(uuid,uuid,jsonb) from public, anon, authenticated;

create function private.ops_photo_ack(conf uuid, cid uuid, actor uuid, command jsonb) returns uuid
language plpgsql set search_path='' as $$
declare slot public.photo_slots;
begin
 select * into slot from public.photo_slots where id = private.uuid_or_null(command->>'slotId') and conference_id = conf;
 if not found then raise exception 'Photo slot unavailable' using errcode='22023'; end if;
 if command->>'stage' not in ('warning','due') then raise exception 'Unknown reminder stage' using errcode='22023'; end if;
 -- Acknowledging an older revision is harmless: it simply does not silence the current reminder.
 insert into public.photo_acknowledgements(conference_id, committee_id, slot_id, stage, slot_revision, actor_id)
 values (conf, cid, slot.id, command->>'stage', (command->>'revision')::bigint, actor)
 on conflict (slot_id, committee_id, stage, slot_revision) do nothing;
 return slot.id;
end; $$;
revoke all on function private.ops_photo_ack(uuid,uuid,uuid,jsonb) from public, anon, authenticated;

create or replace function public.operations_snapshot(conf uuid) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object(
  'submissionLinks', (select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'committeeId',l.committee_id,'token',l.token,'shareWith',l.share_with,'createdAt',l.created_at) order by l.created_at, l.id),'[]')
    from public.submission_links l where l.conference_id = conf and l.revoked_at is null),
  'resolutionLinks', (select coalesce(jsonb_agg(jsonb_build_object('documentId',r.document_id,'workingDocId',r.working_doc_id,'approvalCopyDocId',r.approval_copy_doc_id,'access',r.access,'submittedAt',r.submitted_at,'revision',r.revision) order by r.created_at, r.document_id),'[]')
    from public.resolution_links r where r.conference_id = conf),
  'photoSlots', (select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'schoolId',p.school_id,'startsAt',p.starts_at,'endsAt',p.ends_at,'location',p.location,'note',p.note,'enabled',p.enabled,'warnMinutes',p.warn_minutes,'revision',p.revision) order by p.starts_at, p.id),'[]')
    from public.photo_slots p where p.conference_id = conf),
  'photoAcks', (select coalesce(jsonb_agg(jsonb_build_object('slotId',a.slot_id,'committeeId',a.committee_id,'stage',a.stage,'revision',a.slot_revision,'at',a.created_at) order by a.created_at),'[]')
    from public.photo_acknowledgements a where a.conference_id = conf)
 );
$$;

create or replace function private.apply_operations_mutation(conf uuid, mutation uuid, command jsonb, requested_role public.conference_role, expected text, client_time timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor uuid := auth.uid(); kind text := command->>'type'; cid uuid; entity uuid; affected uuid[] := '{}'; c uuid; topic text := 'configuration';
 allowed public.conference_role[] := array['admin']::public.conference_role[];
 prior private.mutation_receipts;
 new_id uuid := (substr(mutation::text,1,24)||'000000000001')::uuid;
 payload jsonb := jsonb_build_object('command',command,'role',requested_role,'expected',expected,'client_time',client_time);
begin
 if actor is null then raise exception 'Session required' using errcode='42501'; end if;
 if pg_column_size(command) > 262144 then raise exception 'Command too large' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(mutation::text,0));
 select * into prior from private.mutation_receipts where id = mutation;
 if found then
   if prior.actor_id <> actor or prior.conference_id <> conf or prior.payload <> payload then raise exception 'Idempotency key reused for a different action' using errcode='22023'; end if;
   return;
 end if;
 case kind
 when 'submissionLink', 'photoAck' then
   cid := private.uuid_or_null(command->>'committeeId');
   if cid is null or not exists(select 1 from public.committees where id = cid and conference_id = conf) then raise exception 'Committee unavailable' using errcode='22023'; end if;
   if kind = 'photoAck' then allowed := array['chair']::public.conference_role[]; topic := 'chair'; end if;
 when 'resolutionLink' then
   select committee_id into cid from public.documents where id = private.uuid_or_null(command->>'documentId') and conference_id = conf;
   if cid is null then raise exception 'Document unavailable' using errcode='42501'; end if;
   allowed := array['chair','admin']::public.conference_role[]; topic := 'documents';
 when 'sessionImport', 'photoSlot', 'photoImport' then cid := null;
 else raise exception 'Unknown operations command' using errcode='22023';
 end case;
 if not requested_role = any(allowed) then raise exception '% access required', case when 'chair' = any(allowed) then 'Chair' else 'Executive' end using errcode='42501'; end if;
 if not private.has_access(conf, cid, array[requested_role]) then raise exception 'This session has no access to this role or committee' using errcode='42501'; end if;
 if cid is not null then perform 1 from public.committees where id = cid and conference_id = conf for update;
 else perform 1 from public.conferences where id = conf for update; end if;
 case kind
 when 'submissionLink' then entity := private.ops_submission_link(conf, cid, actor, new_id, command);
 when 'resolutionLink' then entity := private.ops_resolution_link(conf, cid, command);
 when 'sessionImport' then affected := private.ops_session_import(conf, mutation, command);
 when 'photoSlot' then affected := private.ops_photo_slot(conf, new_id, command); entity := coalesce(private.uuid_or_null(command->>'slotId'), new_id);
 when 'photoImport' then affected := private.ops_photo_import(conf, mutation, command);
 when 'photoAck' then entity := private.ops_photo_ack(conf, cid, actor, command);
 end case;
 insert into public.audit_log(conference_id, committee_id, "actorId", action, "entityId", mutation_id, details)
 values (conf, cid, actor, kind || ' ' || coalesce(command->>'action', command->>'stage', 'updated'), coalesce(entity, cid, conf), mutation,
   case kind when 'submissionLink' then command - 'token' when 'sessionImport' then jsonb_build_object('type', kind, 'rows', jsonb_array_length(command->'rows'))
             when 'photoImport' then jsonb_build_object('type', kind, 'rows', jsonb_array_length(command->'rows')) else command end);
 insert into private.mutation_receipts(id, conference_id, actor_id, payload) values (mutation, conf, actor, payload);
 insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, cid, topic, mutation);
 -- Chairs subscribe per committee: notify each affected committee as well (one small row each).
 foreach c in array affected loop
   continue when c is not distinct from cid;
   insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, c, 'configuration', gen_random_uuid());
 end loop;
end; $$;
insert into supabase_migrations.schema_migrations(version,name,statements) values('20261006023106','photo_schedule',array[$ledger$-- applied from supabase/migrations/20261006023106_photo_schedule.sql (sha256 76a81cef42a0c54c8f6ee55844584563c5f14c3b4d7d9863df14a08fd0a7c2b5)$ledger$]);

-- ===== 20261006023108_operations_review_hardening.sql (sha256 f3eefb733061eb1e195070dc5cb1462e3dcd8f3a427c45c3b7436110f79e482e) =====
-- Review hardening for Claude operations PRs #3–#5. Created with the Supabase CLI;
-- ordered after the three not-yet-applied extension migrations to preserve their dependencies.
-- No public reads or direct writes are added. Core mutation/outbox contract remains independent.

-- Link visibility must follow the document lifecycle, just like versions and comments.
drop policy read_authorized on public.resolution_links;
create policy read_authorized on public.resolution_links for select to authenticated
 using (exists(select 1 from public.documents d where d.id = resolution_links.document_id));

-- A folder prefix alone must never authorize unsubmitted or orphaned uploaded bytes.
do $$ begin
 if exists(select 1 from pg_namespace where nspname = 'storage') then
   execute 'drop policy if exists resolutions_staff_read on storage.objects';
   execute $p$create policy resolutions_staff_read on storage.objects for select to authenticated using (
     bucket_id = 'resolutions' and exists (
       select 1 from public.document_versions v where v."storageKey" = storage.objects.name
       and private.has_access(v.conference_id,v.committee_id,array['admin','chair','approval','logistics']::public.conference_role[])
     ))$p$;
 end if;
end $$;
create index document_versions_storage_key on public.document_versions("storageKey") where "storageKey" is not null;
create policy no_browser_access on private.resolution_submissions for all to anon,authenticated using(false) with check(false);

-- Bind a receipt to its exact logical input, including committee, link and source bytes.
alter table private.resolution_submissions add column request_payload jsonb;
update private.resolution_submissions s set request_payload = jsonb_build_object(
 'submitter',d."submitterId",'title',trim(d.title),'googleDocId',s.google_doc_id,
 'fileName',case when s.google_doc_id is null then v."fileName" else null end,
 'storageKey',v."storageKey",'sha256',s.file_sha256,'size',s.file_size)
from public.documents d, public.document_versions v
where d.id=s.document_id and v."documentId"=d.id and v.number=1;
alter table private.resolution_submissions alter column request_payload set not null;

create or replace function public.submit_resolution(link_token text, submission uuid, submitter uuid, title text, google_doc_id text,
  file_name text, storage_key text, file_sha256 text, file_size integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 link public.submission_links; existing private.resolution_submissions; sid uuid; n integer; doc_code text; committee_code text;
 doc_id uuid := (substr(submission::text,1,24)||'000000000001')::uuid;
 version_id uuid := (substr(submission::text,1,24)||'000000000002')::uuid;
 submitter_country text; request_payload jsonb;
begin
 select * into link from public.submission_links where token = link_token and revoked_at is null;
 if not found then raise exception 'invalid_link' using errcode='P0001'; end if;
 if (submit_resolution.google_doc_id is null) = (storage_key is null) then raise exception 'invalid_source' using errcode='P0001'; end if;
 if submit_resolution.google_doc_id is not null and submit_resolution.google_doc_id !~ '^[A-Za-z0-9_-]{25,100}$' then raise exception 'invalid_google_doc' using errcode='P0001'; end if;
 request_payload := jsonb_build_object('submitter',submitter,'title',trim(title),'googleDocId',google_doc_id,
   'fileName',case when storage_key is null then null else left(file_name,200) end,
   'storageKey',storage_key,'sha256',file_sha256,'size',file_size);
 -- Serialize a submission UUID across committees before acquiring its committee lock.
 perform pg_advisory_xact_lock(hashtextextended('submission:' || submission::text,0));
 -- Serialize submissions per committee (document numbering, duplicate check).
 perform 1 from public.committees where id = link.committee_id for update;
 if not exists(select 1 from public.submission_links where id=link.id and revoked_at is null) then raise exception 'invalid_link' using errcode='P0001'; end if;
 select * into existing from private.resolution_submissions where id = submission;
 if found then
   if existing.link_id <> link.id or existing.conference_id <> link.conference_id or existing.committee_id <> link.committee_id
      or existing.request_payload is distinct from request_payload then
     raise exception 'idempotency_conflict' using errcode='22023';
   end if;
   return jsonb_build_object('status','replayed','code',(select code from public.documents where id = existing.document_id));
 end if;
 select * into existing from private.resolution_submissions s where s.committee_id = link.committee_id
   and (s.google_doc_id = submit_resolution.google_doc_id or s.file_sha256 = submit_resolution.file_sha256) order by s.created_at limit 1;
 if found then
   if not exists(select 1 from public.delegates where id=submitter and committee_id=link.committee_id) then raise exception 'invalid_submitter' using errcode='P0001'; end if;
   insert into private.resolution_submissions(id,conference_id,committee_id,link_id,document_id,google_doc_id,file_sha256,file_size,request_payload)
   values(submission,link.conference_id,link.committee_id,link.id,existing.document_id,submit_resolution.google_doc_id,submit_resolution.file_sha256,submit_resolution.file_size,request_payload);
   return jsonb_build_object('status','duplicate','code',(select code from public.documents where id = existing.document_id),
     'storageKey',(select v."storageKey" from public.document_versions v where v."documentId"=existing.document_id and v.number=1));
 end if;
 if (select count(*) from private.resolution_submissions where link_id = link.id and created_at > now() - interval '10 minutes') >= 20 then
   raise exception 'rate_limited' using errcode='P0001';
 end if;
 select country into submitter_country from public.delegates where id = submitter and committee_id = link.committee_id and conference_id = link.conference_id;
 if submitter_country is null then raise exception 'invalid_submitter' using errcode='P0001'; end if;
 if length(trim(coalesce(title,''))) < 3 or length(title) > 200 then raise exception 'invalid_title' using errcode='P0001'; end if;
 if storage_key is not null and (submit_resolution.file_sha256 is null or coalesce(submit_resolution.file_size, 0) <= 0
     or storage_key not like link.conference_id::text || '/' || link.committee_id::text || '/' || doc_id::text || '/%') then
   raise exception 'invalid_storage_key' using errcode='P0001';
 end if;
 -- The committee's current session: active, else the latest started, else the first scheduled.
 select id into sid from public.sessions s where s.committee_id = link.committee_id
  order by (s.state = 'active') desc, (s."startsAt" <= now()) desc,
           case when s."startsAt" <= now() then s."startsAt" end desc nulls last, s."startsAt" asc
  limit 1;
 if sid is null then raise exception 'no_session' using errcode='P0001'; end if;
 select code into committee_code from public.committees where id = link.committee_id;
 select count(*) + 1 into n from public.documents where committee_id = link.committee_id;
 loop
   doc_code := committee_code || ' / ' || lpad(n::text, 2, '0');
   exit when not exists(select 1 from public.documents where conference_id = link.conference_id and code = doc_code);
   n := n + 1;
 end loop;
 insert into public.documents(id, conference_id, committee_id, "sessionId", "submitterId", code, title, status)
 values (doc_id, link.conference_id, link.committee_id, sid, submitter, doc_code, trim(title), 'Draft');
 insert into public.document_versions(id, conference_id, committee_id, "documentId", number, "fileName", "storageKey", text)
 values (version_id, link.conference_id, link.committee_id, doc_id, 1,
   case when storage_key is null then 'Google Doc' else left(file_name, 200) end, storage_key,
   'Submitted through the ' || committee_code || ' submission link by ' || submitter_country || '.' || chr(10) ||
   case when storage_key is null
     then 'Working document: Google Doc.' || chr(10) || chr(10) || 'The resolution text lives in the Google Doc. Use “Open Google Doc”.'
     else 'Uploaded file (fallback): ' || left(file_name, 200) || ' (' || greatest(1, round(submit_resolution.file_size / 1024.0))::text || ' KB).' || chr(10) || chr(10) || 'Open the submitted file to read it.'
   end);
 insert into public.resolution_links(document_id, conference_id, committee_id, working_doc_id, submitted_at)
 values (doc_id, link.conference_id, link.committee_id, submit_resolution.google_doc_id, now());
 insert into private.resolution_submissions(id, conference_id, committee_id, link_id, document_id, google_doc_id, file_sha256, file_size, request_payload)
 values (submission, link.conference_id, link.committee_id, link.id, doc_id, submit_resolution.google_doc_id, submit_resolution.file_sha256, submit_resolution.file_size, request_payload);
 -- Notifies the committee's Chair through the existing Realtime path.
 insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (link.conference_id, link.committee_id, 'documents', submission);
 return jsonb_build_object('status','created','code',doc_code);
end; $$;

create or replace function private.apply_operations_mutation(conf uuid, mutation uuid, command jsonb, requested_role public.conference_role, expected text, client_time timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor uuid := auth.uid(); kind text := command->>'type'; cid uuid; entity uuid; affected uuid[] := '{}'; c uuid; topic text := 'configuration';
 allowed public.conference_role[] := array['admin']::public.conference_role[];
 prior private.mutation_receipts; actual text;
 new_id uuid := (substr(mutation::text,1,24)||'000000000001')::uuid;
 payload jsonb := jsonb_build_object('command',command,'role',requested_role,'expected',expected,'client_time',client_time);
begin
 if actor is null then raise exception 'Session required' using errcode='42501'; end if;
 if pg_column_size(command) > 262144 then raise exception 'Command too large' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(mutation::text,0));
 select * into prior from private.mutation_receipts where id = mutation;
 if found then
   if prior.actor_id <> actor or prior.conference_id <> conf or prior.payload <> payload then raise exception 'Idempotency key reused for a different action' using errcode='22023'; end if;
   return;
 end if;
 case kind
 when 'submissionLink', 'photoAck' then
   cid := private.uuid_or_null(command->>'committeeId');
   if cid is null or not exists(select 1 from public.committees where id = cid and conference_id = conf) then raise exception 'Committee unavailable' using errcode='22023'; end if;
   if kind = 'photoAck' then allowed := array['chair']::public.conference_role[]; topic := 'chair'; end if;
 when 'resolutionLink' then
   select committee_id into cid from public.documents where id = private.uuid_or_null(command->>'documentId') and conference_id = conf;
   if cid is null then raise exception 'Document unavailable' using errcode='42501'; end if;
   allowed := array['chair','admin']::public.conference_role[]; topic := 'documents';
 when 'sessionImport', 'photoSlot', 'photoImport' then cid := null;
 else raise exception 'Unknown operations command' using errcode='22023';
 end case;
 if not requested_role = any(allowed) then raise exception '% access required', case when 'chair' = any(allowed) then 'Chair' else 'Executive' end using errcode='42501'; end if;
 if not private.has_access(conf, cid, array[requested_role]) then raise exception 'This session has no access to this role or committee' using errcode='42501'; end if;
 if cid is not null then perform 1 from public.committees where id = cid and conference_id = conf for update;
 else perform 1 from public.conferences where id = conf for update; end if;
 -- Compare under the same lock as the write. A missing precondition is not permission to overwrite.
 if kind = 'resolutionLink' then
   select revision::text into actual from public.resolution_links where document_id = private.uuid_or_null(command->>'documentId');
   actual := coalesce(actual,'0');
 elsif kind = 'photoSlot' and command->>'action' = 'update' then
   select revision::text into actual from public.photo_slots where id = private.uuid_or_null(command->>'slotId') and conference_id = conf;
   actual := coalesce(actual,'0');
 elsif kind = 'submissionLink' then
   select id::text || '|' || share_with into actual from public.submission_links where committee_id = cid and revoked_at is null;
   actual := coalesce(actual,'none');
 end if;
 if actual is not null and expected is distinct from actual then
   raise exception 'This item changed on another device. Review the saved change before retrying.' using errcode='40001';
 end if;
 case kind
 when 'submissionLink' then entity := private.ops_submission_link(conf, cid, actor, new_id, command);
 when 'resolutionLink' then entity := private.ops_resolution_link(conf, cid, command);
 when 'sessionImport' then affected := private.ops_session_import(conf, mutation, command);
 when 'photoSlot' then affected := private.ops_photo_slot(conf, new_id, command); entity := coalesce(private.uuid_or_null(command->>'slotId'), new_id);
 when 'photoImport' then affected := private.ops_photo_import(conf, mutation, command);
 when 'photoAck' then entity := private.ops_photo_ack(conf, cid, actor, command);
 end case;
 insert into public.audit_log(conference_id, committee_id, "actorId", action, "entityId", mutation_id, details)
 values (conf, cid, actor, kind || ' ' || coalesce(command->>'action', command->>'stage', 'updated'), coalesce(entity, cid, conf), mutation,
   case kind when 'submissionLink' then command - 'token' when 'sessionImport' then jsonb_build_object('type', kind, 'rows', jsonb_array_length(command->'rows'))
             when 'photoImport' then jsonb_build_object('type', kind, 'rows', jsonb_array_length(command->'rows')) else command end);
 insert into private.mutation_receipts(id, conference_id, actor_id, payload) values (mutation, conf, actor, payload);
 insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, cid, topic, mutation);
 -- Chairs subscribe per committee: notify each affected committee as well (one small row each).
 foreach c in array affected loop
   continue when c is not distinct from cid;
   insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (conf, c, 'configuration', gen_random_uuid());
 end loop;
end; $$;
insert into supabase_migrations.schema_migrations(version,name,statements) values('20261006023108','operations_review_hardening',array[$ledger$-- applied from supabase/migrations/20261006023108_operations_review_hardening.sql (sha256 f3eefb733061eb1e195070dc5cb1462e3dcd8f3a427c45c3b7436110f79e482e)$ledger$]);

-- ===== 20261006023111_chair_procedure.sql (sha256 0675b72b58fcab91bd6260b7e8349eec5c9464ccbd37ae8e6883d4d4077b1ecb) =====
-- Core Chair procedure. Ordered after Claude's three unapplied extensions and review hardening.
-- Operational queues are mutable; delivered speeches, recognized POIs and votes are historical.
alter table public.committees add column "currentSessionId" uuid,
 add column "sessionRevision" bigint not null default 0,
 add column "vetoEnabled" boolean not null default false,
 add column "vetoDelegateIds" uuid[] not null default '{}',
 add foreign key ("currentSessionId",conference_id,id) references public.sessions(id,conference_id,committee_id);
alter table public.documents alter column "sessionId" drop not null;
alter table public.documents add column "voteMode" text not null default 'normal' check ("voteMode" in ('normal','divide')),
 add column "voteType" text not null default 'substantive' check ("voteType" in ('substantive','procedural')),
 add column "vetoedBy" uuid[] not null default '{}';
alter table public.speaker_queue add column lane text not null default 'open' check(lane in ('open','for','against'));
alter table public.speaker_queue alter column position set generated by default;
drop index public.queue_active_delegate;
create unique index queue_active_delegate on public.speaker_queue("sessionId",lane,"delegateId") where state='active';
create index queue_order_idx on public.speaker_queue("sessionId",lane,position) where state='active';
create table public.debate_states (
 "sessionId" uuid primary key, conference_id uuid not null, committee_id uuid not null,
 mode text not null default 'open' check(mode in ('open','closed')),
 phase text not null default 'for' check(phase in ('for','against')), revision bigint not null default 1,
 foreign key("sessionId",conference_id,committee_id) references public.sessions(id,conference_id,committee_id)
);
create table public.speeches (
 id uuid primary key, conference_id uuid not null, committee_id uuid not null,
 "sessionId" uuid not null, "delegateId" uuid not null, "resolutionId" uuid,
 classification text not null check(classification in ('Main Submitter','Co-Submitter','For','Against','Other')),
 "yieldedFrom" uuid, state text not null default 'speaking' check(state in ('speaking','pois','finished')),
 "poiLimit" integer default 0 check("poiLimit" between 0 and 1000), "poiCount" integer not null default 0,
 revision bigint not null default 1, "createdAt" timestamptz not null default now(),
 unique(id,conference_id,committee_id),
 foreign key("sessionId",conference_id,committee_id) references public.sessions(id,conference_id,committee_id),
 foreign key("delegateId",conference_id,committee_id) references public.delegates(id,conference_id,committee_id),
 foreign key("resolutionId",conference_id,committee_id) references public.documents(id,conference_id,committee_id),
 foreign key("yieldedFrom",conference_id,committee_id) references public.speeches(id,conference_id,committee_id),
 check((classification='Co-Submitter')=("yieldedFrom" is not null))
);
create unique index speech_one_floor on public.speeches("sessionId") where state<>'finished';
create table public.poi_queue (
 id uuid primary key, conference_id uuid not null, committee_id uuid not null,
 "speechId" uuid not null, "delegateId" uuid not null, position bigint not null,
 unique("speechId","delegateId"),
 foreign key("speechId",conference_id,committee_id) references public.speeches(id,conference_id,committee_id),
 foreign key("delegateId",conference_id,committee_id) references public.delegates(id,conference_id,committee_id)
);
alter table public.participation_events add column "speechId" uuid, add column classification text, add column "yieldedFrom" uuid,
 add foreign key("speechId",conference_id,committee_id) references public.speeches(id,conference_id,committee_id),
 add foreign key("yieldedFrom",conference_id,committee_id) references public.speeches(id,conference_id,committee_id);
create unique index speech_one_event on public.participation_events("speechId") where "categoryId"='speech';
-- Legacy duplicate main-submitter entries are preserved as history; new writes check under committee lock.
create index main_submitter_credit_idx on public.participation_events("resolutionId") where "categoryId"='submitter';
DO $$ declare t text; begin
 foreach t in array array['debate_states','speeches','poi_queue'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy read_authorized on public.%I for select to authenticated using(private.has_access(conference_id,committee_id,array[''chair'',''admin'',''observer'']::public.conference_role[]))',t);
 end loop;
end $$;
create or replace function public.conference_snapshot(conf uuid) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if not exists(select 1 from public.conferences where id=conf) then raise exception 'Conference access has not been granted' using errcode='42501'; end if;
 select jsonb_build_object(
 'conference',(select jsonb_build_object('id',id,'name',name,'venue',venue,'date',date,'features',features,'votingRule',voting_rule) from public.conferences where id=conf),
 'committees',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('conferenceId',conference_id,'votingRule',voting_rule,'scoringOverrides',(select jsonb_agg(jsonb_build_object('id',code,'label',label,'values',values)) from public.scoring_definitions s where s.committee_id=x.id)) order by x.created_at,x.id),'[]') from public.committees x where conference_id=conf),
 'schools',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.schools x where conference_id=conf),
 'staff',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('role',coalesce((select role::text from public.conference_staff f where f.staff_id=x.id limit 1),'chair'),'committeeIds',(select coalesce(jsonb_agg(committee_id),'[]') from public.committee_staff a where a.staff_id=x.id)) order by x.created_at,x.id),'[]') from public.staff x where conference_id=conf),
 'sessions',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('committeeId',committee_id) order by x.created_at,x.id),'[]') from public.sessions x where conference_id=conf),
 'delegates',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('committeeId',committee_id) order by x.created_at,x.id),'[]') from public.delegates x where conference_id=conf),
 'attendance',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.attendance x where conference_id=conf),
 'documents',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('committeeId',committee_id,'versionIds',(select coalesce(jsonb_agg(v.id order by number),'[]') from public.document_versions v where v."documentId"=x.id),'comments',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'text',text,'authorId',"authorId",'createdAt',"createdAt") order by "createdAt"),'[]') from public.document_comments c where c."documentId"=x.id)) order by x.created_at,x.id),'[]') from public.documents x where conference_id=conf),
 'versions',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.document_versions x where conference_id=conf),
 'events',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('speechId',(select e."speechId" from public.participation_events e where e.id=x.id),'classification',(select e.classification from public.participation_events e where e.id=x.id),'yieldedFrom',(select e."yieldedFrom" from public.participation_events e where e.id=x.id),'points',effective_points,'voidedAt',voided_at,'updatedAt',corrected_at,'revision',(select count(*) from public.participation_corrections c where c.event_id=x.id)) order by x.created_at,x.id),'[]') from public.participation_history x where conference_id=conf),
 'queue',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.speaker_queue x where conference_id=conf and state='active'),
 'votes',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.votes x where conference_id=conf),
 'scoring',(select coalesce(jsonb_agg(jsonb_build_object('id',code,'label',label,'values',values) order by x.created_at,x.id),'[]') from public.scoring_definitions x where conference_id=conf and committee_id is null),
 'criteria',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' || jsonb_build_object('committeeId',committee_id) order by x.created_at,x.id),'[]') from public.award_criteria x where conference_id=conf),
 'awardScores',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.award_scores x where conference_id=conf),
 'audit',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'-'created_at'-'updated_at' order by x.created_at,x.id),'[]') from public.audit_log x where conference_id=conf),
 'timers',(select coalesce(jsonb_object_agg("sessionId",jsonb_build_object('duration',duration,'remaining',remaining,'startedAt',"startedAt",'revision',revision)),'{}') from public.timers where conference_id=conf)
 ) into result;
 return result || jsonb_build_object(
 'debateStates',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'),'[]') from public.debate_states x where conference_id=conf),
 'speeches',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'),'[]') from public.speeches x where conference_id=conf),
 'poiQueue',(select coalesce(jsonb_agg(to_jsonb(x)-'conference_id'-'committee_id'),'[]') from public.poi_queue x where conference_id=conf));
end; $$;
revoke all on function public.conference_snapshot(uuid) from public,anon;
grant execute on function public.conference_snapshot(uuid) to authenticated;
create function private.veto_delegates(rid uuid) returns uuid[] language sql stable set search_path='' as $$
 select coalesce(array_agg(v."delegateId" order by v."delegateId"),'{}') from public.documents d
 join public.committees c on c.id=d.committee_id
 join public.votes v on v."resolutionId"=d.id and v."sessionId"=d."sessionId" and v.choice='Against'
 join public.attendance a on a."delegateId"=v."delegateId" and a."sessionId"=v."sessionId" and a.status<>'Absent'
 where d.id=rid and c."vetoEnabled" and d."voteType"='substantive' and v."delegateId"=any(c."vetoDelegateIds");
$$;
revoke all on function private.veto_delegates(uuid) from public,anon,authenticated;
create or replace function private.apply_mutation(conf uuid, mutation uuid, command jsonb, requested_role public.conference_role, expected text, client_time timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor uuid:=auth.uid(); kind text:=command->>'type'; cid uuid; sid uuid; did uuid;
 rid uuid; entity uuid; rec public.documents; att public.attendance; ev public.participation_events;
 prior private.mutation_receipts; actual text; vals integer[]; target text:=command->>'status';
 new_id uuid:=(substr(mutation::text,1,24)||'000000000001')::uuid;
 second_id uuid:=(substr(mutation::text,1,24)||'000000000002')::uuid;
 payload jsonb:=jsonb_build_object('command',command,'role',requested_role,'expected',expected,'client_time',client_time);
 n integer; yes_votes integer; no_votes integer; rule text; result public.document_outcome;
 row_data jsonb; category text; topic text:='chair';
begin
 if actor is null then raise exception 'Session required' using errcode='42501'; end if;
 if pg_column_size(command)>1048576 then raise exception 'Command too large' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(mutation::text,0));
 select * into prior from private.mutation_receipts where id=mutation;
 if found then
   if prior.actor_id<>actor or prior.conference_id<>conf or prior.payload<>payload then raise exception 'Idempotency key reused for a different action' using errcode='22023'; end if;
   return;
 end if;
 if kind in ('document','version') then
   rid:=(command->>'id')::uuid;
   select * into rec from public.documents where id=rid and conference_id=conf;
   if not found then raise exception 'Document unavailable' using errcode='42501'; end if;
   cid:=rec.committee_id; sid:=rec."sessionId";
 elsif kind='event' then
   select * into ev from public.participation_events where id=(command->>'id')::uuid and conference_id=conf;
   if not found then raise exception 'Event unavailable' using errcode='42501'; end if;
   cid:=ev.committee_id; sid:=ev."sessionId";
 elsif command ? 'sessionId' then
   sid:=(command->>'sessionId')::uuid;
   select committee_id into cid from public.sessions where id=sid and conference_id=conf;
   if cid is null then raise exception 'Session unavailable' using errcode='42501'; end if;
 elsif kind in ('delegate','award') then
   did:=coalesce(command->>'delegateId',command->>'id')::uuid;
   select committee_id into cid from public.delegates where id=did and conference_id=conf;
 else cid:=nullif(command->>'committeeId','')::uuid;
 end if;
 if not private.has_access(conf,cid,array[requested_role]) then raise exception 'This session has no access to this role or committee' using errcode='42501'; end if;
 if kind in ('attendance','participation','event','queue','timer','vote','newDocument','version','award') and requested_role<>'chair' then raise exception 'Chair access required' using errcode='42501'; end if;
 if kind not in ('attendance','participation','event','queue','timer','vote','newDocument','version','award','document') and requested_role<>'admin' then raise exception 'Administrator access required' using errcode='42501'; end if;
 -- A committee's short transactions serialize queue, attendance and voting boundaries.
 -- Independent committees use different row locks; no conference-wide chair lock.
 if cid is not null then perform 1 from public.committees where id=cid and conference_id=conf for update;
 else perform 1 from public.conferences where id=conf for update; end if;
 if command ? 'delegateId' then
   did:=(command->>'delegateId')::uuid;
   if not exists(select 1 from public.delegates where id=did and conference_id=conf and committee_id=cid) then raise exception 'Delegate outside committee' using errcode='22023'; end if;
 end if;
 if command->>'resolutionId' is not null then
   rid:=(command->>'resolutionId')::uuid;
   if not exists(select 1 from public.documents where id=rid and conference_id=conf and committee_id=cid ) then raise exception 'Resolution outside committee' using errcode='22023'; end if;
 end if;
 if kind in ('document','version') then
   select * into rec from public.documents where id=rid;
   actual:=rec.revision::text;
 elsif kind='attendance' then select * into att from public.attendance where "sessionId"=sid and "delegateId"=did; actual:=coalesce(att.revision,0)::text;
 elsif kind='event' then select count(*)::text into actual from public.participation_corrections where event_id=ev.id;
 elsif kind='timer' then select coalesce((select revision from public.timers where "sessionId"=sid),0)::text into actual;
 elsif kind='vote' then select coalesce((select revision from public.votes where "sessionId"=sid and "delegateId"=did and "resolutionId"=rid),0)::text into actual;
 elsif kind='queue' and coalesce((command->>'advance')::boolean,false) then select coalesce((select id::text from public.speaker_queue where "sessionId"=sid and state='active' order by position limit 1),'empty') into actual;
 end if;
 if actual is not null and actual is distinct from expected then raise exception 'Another chair updated this item. Review before applying your change.' using errcode='40001'; end if;
 case kind
 when 'attendance' then
   insert into public.attendance(id,conference_id,committee_id,"sessionId","delegateId",status)
   values(new_id,conf,cid,sid,did,target::public.attendance_state)
   on conflict("sessionId","delegateId") do update set status=excluded.status,"updatedAt"=now(),revision=attendance.revision+1,updated_at=now();
   -- A closed vote is historical. Subsequent roll call must not rewrite it.
   delete from public.votes v using public.documents d where v."resolutionId"=d.id and d.status<>'Closed' and v."sessionId"=sid and v."delegateId"=did and (target='Absent' or (target='Present & Voting' and v.choice='Abstain'));
   if target='Absent' then update public.speaker_queue set state='removed',updated_at=now() where "sessionId"=sid and "delegateId"=did and state='active'; end if;
 when 'participation' then
   category:=command->>'categoryId';
   if category='submitter' and (rid is null or (select "submitterId" from public.documents where id=rid) is distinct from did or exists(select 1 from public.participation_events where "resolutionId"=rid and "categoryId"='submitter')) then raise exception 'Main Submitter credit already recorded or resolution missing' using errcode='22023'; end if;
   select values into vals from public.scoring_definitions where conference_id=conf and code=category and (committee_id=cid or committee_id is null) order by committee_id nulls last limit 1;
   if vals is null or not (command->>'points')::integer=any(vals) then raise exception 'Invalid scoring value' using errcode='22023'; end if;
   insert into public.participation_events(id,conference_id,committee_id,"delegateId","sessionId","resolutionId","categoryId",points,"chairId","createdAt")
   values(new_id,conf,cid,did,sid,rid,category,(command->>'points')::integer,actor,client_time);
 when 'event' then
   select values into vals from public.scoring_definitions where conference_id=conf and code=ev."categoryId" and (committee_id=cid or committee_id is null) order by committee_id nulls last limit 1;
   if not coalesce((command->>'undo')::boolean,false) and (vals is null or not (command->>'points')::integer=any(vals)) then raise exception 'Invalid scoring value' using errcode='22023'; end if;
   insert into public.participation_corrections(id,conference_id,committee_id,event_id,points,voided,actor_id)
   values(new_id,conf,cid,ev.id,(command->>'points')::integer,coalesce((command->>'undo')::boolean,false),actor);
 when 'queue' then
   if coalesce((command->>'advance')::boolean,false) then
     update public.speaker_queue set state='completed',updated_at=now() where id=nullif(actual,'empty')::uuid;
     insert into public.timers(conference_id,committee_id,"sessionId",duration,remaining,"startedAt") values(conf,cid,sid,90,90,null)
     on conflict("sessionId") do update set remaining=timers.duration,"startedAt"=null,revision=timers.revision+1,updated_at=now();
   else
     if not exists(select 1 from public.attendance where "sessionId"=sid and "delegateId"=did and status<>'Absent') then raise exception 'Delegate must be present' using errcode='22023'; end if;
     insert into public.speaker_queue(id,conference_id,committee_id,"sessionId","delegateId") values(new_id,conf,cid,sid,did) on conflict do nothing;
   end if;
 when 'timer' then
   insert into public.timers(id,conference_id,committee_id,"sessionId",duration,remaining,"startedAt") values(new_id,conf,cid,sid,(command->>'duration')::integer,(command->>'remaining')::numeric,(command->>'startedAt')::bigint)
   on conflict("sessionId") do update set duration=excluded.duration,remaining=excluded.remaining,"startedAt"=excluded."startedAt",revision=timers.revision+1,updated_at=now();
 when 'vote' then
   if exists(select 1 from public.documents where id=rid and ("sessionId" is distinct from sid or ("voteMode"='divide' and command->>'choice'='Abstain'))) then raise exception 'Vote session or mode does not permit this ballot' using errcode='22023'; end if;
   if not exists(select 1 from public.documents where id=rid and status='In Debate') then raise exception 'Voting requires active debate' using errcode='22023'; end if;
   if not exists(select 1 from public.attendance where "sessionId"=sid and "delegateId"=did and status<>'Absent' and (status<>'Present & Voting' or command->>'choice'<>'Abstain')) then raise exception 'Attendance does not permit vote' using errcode='22023'; end if;
   insert into public.votes(id,conference_id,committee_id,"sessionId","delegateId","resolutionId",choice) values(new_id,conf,cid,sid,did,rid,command->>'choice')
   on conflict("delegateId","sessionId","resolutionId") do update set choice=excluded.choice,revision=votes.revision+1,"createdAt"=now(),updated_at=now();
 when 'document' then
   topic:='documents';
   if not ((requested_role='chair' and ((rec.status='Draft' and target='Submitted') or (rec.status='Printed' and target='In Debate') or (rec.status='In Debate' and target='Closed')))
     or (requested_role='approval' and rec.status in ('Submitted','Review') and target in ('Review','Approved','Draft') and rec.status::text<>target)
     or (requested_role='logistics' and rec.status='Approved' and target='Printed')) then raise exception 'Transition not allowed for this role' using errcode='22023'; end if;
   if target='Draft' and length(trim(coalesce(command->>'comment','')))=0 then raise exception 'A change request requires a comment' using errcode='22023'; end if;
   if target='In Debate' and (select "currentSessionId" from public.committees where id=cid) is null then raise exception 'Select the current session first' using errcode='22023'; end if;
   if target='Closed' then
     if command->>'outcome'='Withdrawn' then result:='Withdrawn';
     else
       select count(*) into n from public.attendance where "sessionId"=sid and status<>'Absent';
       if n=0 or n<>(select count(*) from public.votes where "resolutionId"=rid and "sessionId"=sid) then raise exception 'Record every eligible ballot before closing' using errcode='22023'; end if;
       select count(*) filter(where choice='For'),count(*) filter(where choice='Against') into yes_votes,no_votes from public.votes where "resolutionId"=rid and "sessionId"=sid;
       select coalesce(c.voting_rule,f.voting_rule) into rule from public.committees c join public.conferences f on f.id=c.conference_id where c.id=cid;
       result:=case when yes_votes+no_votes>0 and ((rule='simple_majority' and yes_votes>no_votes) or (rule='two_thirds' and yes_votes*3>=(yes_votes+no_votes)*2)) then 'Passed'::public.document_outcome else 'Failed'::public.document_outcome end;
       if cardinality(private.veto_delegates(rid))>0 then result:='Failed'; end if;
       if command->>'outcome' is distinct from result::text then raise exception 'Outcome differs from configured voting rule' using errcode='22023'; end if;
     end if;
   end if;
   update public.documents set "vetoedBy"=case when target='Closed' and result<>'Withdrawn' then private.veto_delegates(rid) else "vetoedBy" end,
    "sessionId"=case when target='In Debate' then (select "currentSessionId" from public.committees where id=cid) else "sessionId" end,
    status=target::public.document_state,outcome=result,revision=revision+1,updated_at=now() where id=rid;
   if length(trim(coalesce(command->>'comment','')))>0 then insert into public.document_comments(id,conference_id,committee_id,"documentId",text,"authorId") values(new_id,conf,cid,rid,command->>'comment',actor); end if;
 when 'version' then
   topic:='documents';
   if rec.status<>'Draft' then raise exception 'New versions require draft state' using errcode='22023'; end if;
   select coalesce(max(number),0)+1 into n from public.document_versions where "documentId"=rid;
   insert into public.document_versions(id,conference_id,committee_id,"documentId",number,"createdBy","fileName",text) values(new_id,conf,cid,rid,n,actor,command->>'fileName',command->>'text');
   update public.documents set revision=revision+1,updated_at=now() where id=rid;
 when 'newDocument' then
   topic:='documents';
   if cid is distinct from (command->>'committeeId')::uuid then raise exception 'Session outside committee' using errcode='22023'; end if;
   insert into public.documents(id,conference_id,committee_id,"sessionId","submitterId",code,title) select new_id,conf,cid,sid,(command->>'submitterId')::uuid,c.code||' / '||substr(new_id::text,1,8),command->>'title' from public.committees c where c.id=cid;
   insert into public.document_versions(id,conference_id,committee_id,"documentId",number,"createdBy","fileName",text) values(second_id,conf,cid,new_id,1,actor,'draft-preview.txt',command->>'title');
 when 'award' then raise exception 'Award rubrics retired' using errcode='22023';
 when 'committee' then
   topic:='configuration'; insert into public.committees(id,conference_id,code,name,room) values(new_id,conf,trim(command->>'code'),command->>'name',command->>'room');
 when 'session' then
   topic:='configuration'; insert into public.sessions(id,conference_id,committee_id,name,"startsAt",state) values(new_id,conf,cid,command->>'name',now(),'scheduled');
 when 'school' then
   topic:='configuration'; insert into public.schools(id,conference_id,name) values(new_id,conf,command->>'name');
 when 'delegate' then
   topic:='configuration'; update public.delegates set name=command->>'name',email=lower(command->>'email'),country=command->>'country',updated_at=now() where id=did and conference_id=conf;
 when 'import' then
   topic:='configuration'; n:=0;
   for row_data in select * from jsonb_array_elements(command->'rows') loop
     n:=n+1;
     if length(trim(row_data->>'name'))=0 or length(trim(row_data->>'country'))=0 or row_data->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid imported delegate' using errcode='22023'; end if;
     insert into public.delegates(id,conference_id,committee_id,"schoolId",country,name,email) values((substr(mutation::text,1,24)||lpad(to_hex(n),12,'0'))::uuid,conf,(row_data->>'committeeId')::uuid,(row_data->>'schoolId')::uuid,row_data->>'country',row_data->>'name',lower(row_data->>'email'));
   end loop;
 when 'conference' then
   topic:='configuration'; update public.conferences set name=command->>'name',venue=command->>'venue',date=(command->>'date')::date,updated_at=now() where id=conf;
 when 'feature' then
   topic:='configuration'; update public.conferences set features=jsonb_set(features,array[command->>'name'],command->'enabled'),updated_at=now() where id=conf;
 when 'scoring' then
   topic:='configuration'; select array_agg(value::integer) into vals from jsonb_array_elements_text(command->'values');
   insert into public.scoring_definitions(conference_id,committee_id,code,label,values) select conf,cid,command->>'id',label,vals from public.scoring_definitions where conference_id=conf and committee_id is null and code=command->>'id'
   on conflict(conference_id,committee_id,code) do update set values=excluded.values,updated_at=now();
 when 'criterion' then raise exception 'Award rubrics retired' using errcode='22023';
 when 'staff' then
   topic:='configuration'; insert into public.staff(id,conference_id,name) values(new_id,conf,command->>'name');
   insert into public.conference_staff(conference_id,staff_id,role) values(conf,new_id,(command->>'role')::public.conference_role);
   for row_data in select * from jsonb_array_elements(command->'committeeIds') loop insert into public.committee_staff(conference_id,committee_id,staff_id) values(conf,(row_data#>>'{}')::uuid,new_id); end loop;
 else raise exception 'Unknown conference command' using errcode='22023';
 end case;
 entity:=coalesce(rid,did,ev.id,cid,conf);
 if kind<>'queue' then insert into public.audit_log(conference_id,committee_id,"actorId",action,"entityId",mutation_id,details) values(conf,cid,actor,case when kind='document' then 'Resolution → '||target else kind||' updated' end,entity,mutation,command); end if;
 insert into private.mutation_receipts(id,conference_id,actor_id,payload) values(mutation,conf,actor,payload);
 -- The timer has no Realtime event: countdown and start/pause/reset remain local calculations.
 if kind<>'timer' then insert into public.operational_changes(conference_id,committee_id,topic,mutation_id) values(conf,cid,topic,mutation); end if;
end; $$;
revoke all on function private.apply_mutation(uuid,uuid,jsonb,public.conference_role,text,timestamptz) from public,anon;
grant execute on function private.apply_mutation(uuid,uuid,jsonb,public.conference_role,text,timestamptz) to authenticated;

create function private.apply_procedure(conf uuid, mutation uuid, command jsonb, requested_role public.conference_role, expected text, client_time timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare
 actor uuid:=auth.uid(); kind text:=command->>'type'; cid uuid; sid uuid:=private.uuid_or_null(command->>'sessionId');
 did uuid:=private.uuid_or_null(command->>'delegateId'); rid uuid:=private.uuid_or_null(command->>'resolutionId');
 sp public.speeches; r public.documents; prior private.mutation_receipts; actual text; ids uuid[]; entry uuid;
 new_id uuid:=(substr(mutation::text,1,24)||'000000000001')::uuid;
 second_id uuid:=(substr(mutation::text,1,24)||'000000000002')::uuid;
 payload jsonb:=jsonb_build_object('command',command,'role',requested_role,'expected',expected,'client_time',client_time);
 lane_value text:=command->>'lane'; classification_value text:=command->>'classification'; n integer; points_value integer:=(command->>'points')::integer;
begin
 if actor is null then raise exception 'Session required' using errcode='42501'; end if;
 if pg_column_size(command)>262144 then raise exception 'Command too large' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(mutation::text,0));
 select * into prior from private.mutation_receipts where id=mutation;
 if found then
  if prior.actor_id<>actor or prior.conference_id<>conf or prior.payload<>payload then raise exception 'Idempotency key reused for a different action' using errcode='22023'; end if;
  return;
 end if;
 if kind='vetoRules' then cid:=private.uuid_or_null(command->>'committeeId');
 else select committee_id into cid from public.sessions where id=sid and conference_id=conf; end if;
 if cid is null or not exists(select 1 from public.committees where id=cid and conference_id=conf) then raise exception 'Committee unavailable' using errcode='42501'; end if;
 if requested_role<>(case when kind='vetoRules' then 'admin'::public.conference_role else 'chair'::public.conference_role end) or not private.has_access(conf,cid,array[requested_role]) then raise exception 'Access denied' using errcode='42501'; end if;
 perform 1 from public.committees where id=cid for update;
 if did is not null and not exists(select 1 from public.attendance where "sessionId"=sid and "delegateId"=did and status<>'Absent') then raise exception 'Delegate must be present' using errcode='22023'; end if;
 if command ? 'speechId' then
  select * into sp from public.speeches where id=private.uuid_or_null(command->>'speechId') and "sessionId"=sid and conference_id=conf;
  if not found or sp.state='finished' then raise exception 'Speech has finished or is unavailable' using errcode='22023'; end if;
 end if;
 if kind='currentSession' then
  if cid is distinct from private.uuid_or_null(command->>'committeeId') then raise exception 'Session outside committee' using errcode='22023'; end if;
  select "sessionRevision"::text into actual from public.committees where id=cid;
 elsif kind='debateMode' then select coalesce((select revision from public.debate_states where "sessionId"=sid),0)::text into actual;
 elsif kind='queueOrder' then select coalesce(string_agg(id::text,',' order by position),'') into actual from public.speaker_queue where "sessionId"=sid and lane=lane_value and state='active';
 elsif kind='poiOrder' then select coalesce(string_agg(id::text,',' order by position),'') into actual from public.poi_queue where "speechId"=sp.id;
 elsif kind='speechStart' then select coalesce((select id::text from public.speeches where "sessionId"=sid and state<>'finished'),'empty') into actual;
 elsif kind in ('speechYield','speechFinish','poiAllowance','poiRecognize') then actual:=sp.revision::text;
 elsif kind='voteMode' then select revision::text into actual from public.documents where id=rid and committee_id=cid and conference_id=conf;
 end if;
 if actual is not null and actual is distinct from expected then raise exception 'Another Chair changed this item. Review before applying.' using errcode='40001'; end if;
 case kind
 when 'currentSession' then update public.committees set "currentSessionId"=sid,"sessionRevision"="sessionRevision"+1 where id=cid;
 when 'vetoRules' then
  select coalesce(array_agg(value::uuid),'{}') into ids from jsonb_array_elements_text(command->'delegateIds');
  if exists(select 1 from unnest(ids) x where not exists(select 1 from public.delegates d where d.id=x and d.committee_id=cid)) or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) then raise exception 'Invalid veto delegations' using errcode='22023'; end if;
  update public.committees set "vetoEnabled"=(command->>'enabled')::boolean,"vetoDelegateIds"=ids where id=cid;
 when 'debateMode' then
  insert into public.debate_states("sessionId",conference_id,committee_id,mode,phase) values(sid,conf,cid,command->>'mode',command->>'phase')
  on conflict("sessionId") do update set mode=excluded.mode,phase=excluded.phase,revision=debate_states.revision+1;
 when 'queueAdd' then
  select coalesce(max(position),-1)+1 into n from public.speaker_queue where "sessionId"=sid and lane=lane_value and state='active';
  insert into public.speaker_queue(id,conference_id,committee_id,"sessionId","delegateId",lane,position) values(new_id,conf,cid,sid,did,lane_value,n) on conflict do nothing;
 when 'queueRemove' then update public.speaker_queue set state='removed' where id=private.uuid_or_null(command->>'entryId') and "sessionId"=sid;
 when 'queueOrder' then
  select coalesce(array_agg(value::uuid),'{}') into ids from jsonb_array_elements_text(command->'ids');
  if cardinality(ids)<>(select count(*) from public.speaker_queue where "sessionId"=sid and lane=lane_value and state='active') or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not exists(select 1 from public.speaker_queue q where q.id=x and q."sessionId"=sid and q.lane=lane_value and q.state='active')) then raise exception 'Queue changed' using errcode='40001'; end if;
  update public.speaker_queue set position=array_position(ids,id)-1 where id=any(ids);
 when 'speechStart' then
  if exists(select 1 from public.speeches where "sessionId"=sid and state<>'finished') then raise exception 'Return the floor to Chair first' using errcode='22023'; end if;
  if rid is not null then
   select * into r from public.documents where id=rid and committee_id=cid and conference_id=conf and status='In Debate';
   if not found then raise exception 'Resolution must be in debate' using errcode='22023'; end if;
  end if;
  if classification_value='Co-Submitter' or (classification_value='Main Submitter' and (rid is null or r."submitterId" is distinct from did)) then raise exception 'Invalid speech relationship' using errcode='22023'; end if;
  if command ? 'entryId' then
   update public.speaker_queue set state='completed' where id=private.uuid_or_null(command->>'entryId') and "sessionId"=sid and "delegateId"=did and state='active';
   if not found then raise exception 'Queue entry changed' using errcode='40001'; end if;
  end if;
  insert into public.speeches(id,conference_id,committee_id,"sessionId","delegateId","resolutionId",classification,"createdAt") values(new_id,conf,cid,sid,did,rid,classification_value,client_time);
 when 'speechYield' then
  if sp.classification<>'Main Submitter' or sp."resolutionId" is null or did=sp."delegateId" then raise exception 'Only Main Submitter may yield to another delegate' using errcode='22023'; end if;
  update public.speeches set state='finished',revision=revision+1 where id=sp.id;
  delete from public.poi_queue where "speechId"=sp.id;
  insert into public.speeches(id,conference_id,committee_id,"sessionId","delegateId","resolutionId",classification,"yieldedFrom","createdAt") values(new_id,conf,cid,sid,did,sp."resolutionId",'Co-Submitter',sp.id,client_time);
 when 'speechScore' then
  if points_value is null or points_value not between 1 and 3 then raise exception 'Speech points must be 1–3' using errcode='22023'; end if;
  insert into public.participation_events(id,conference_id,committee_id,"delegateId","sessionId","resolutionId","categoryId",points,"chairId","createdAt","speechId",classification,"yieldedFrom") values(new_id,conf,cid,sp."delegateId",sid,sp."resolutionId",'speech',points_value,actor,client_time,sp.id,sp.classification,sp."yieldedFrom");
  if sp.classification='Main Submitter' and not exists(select 1 from public.participation_events where "resolutionId"=sp."resolutionId" and "categoryId"='submitter') then
   insert into public.participation_events(id,conference_id,committee_id,"delegateId","sessionId","resolutionId","categoryId",points,"chairId","createdAt","speechId",classification) values(second_id,conf,cid,sp."delegateId",sid,sp."resolutionId",'submitter',5,actor,client_time,sp.id,sp.classification);
  end if;
 when 'speechFinish' then
  update public.speeches set state='finished',revision=revision+1 where id=sp.id;
  delete from public.poi_queue where "speechId"=sp.id;
 when 'poiAllowance' then
  n:=(command->>'limit')::integer;
  if n is not null and (n<sp."poiCount" or n<0 or n>1000) then raise exception 'Invalid POI allowance' using errcode='22023'; end if;
  update public.speeches set "poiLimit"=n,state='pois',revision=revision+1 where id=sp.id;
 when 'poiAdd' then
  if did=sp."delegateId" then raise exception 'Speaker cannot ask own POI' using errcode='22023'; end if;
  select coalesce(max(position),-1)+1 into n from public.poi_queue where "speechId"=sp.id;
  insert into public.poi_queue(id,conference_id,committee_id,"speechId","delegateId",position) values(new_id,conf,cid,sp.id,did,n) on conflict do nothing;
 when 'poiOrder' then
  select coalesce(array_agg(value::uuid),'{}') into ids from jsonb_array_elements_text(command->'ids');
  if cardinality(ids)<>(select count(*) from public.poi_queue where "speechId"=sp.id) or cardinality(ids)<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not exists(select 1 from public.poi_queue p where p.id=x and p."speechId"=sp.id)) then raise exception 'POI queue changed' using errcode='40001'; end if;
  update public.poi_queue set position=array_position(ids,id)-1 where id=any(ids);
 when 'poiRecognize' then
  if sp.state<>'pois' or (sp."poiLimit" is not null and sp."poiCount">=sp."poiLimit") then raise exception 'Set or extend POIs first' using errcode='22023'; end if;
  if points_value is null or points_value not between 1 and 2 then raise exception 'POI points must be 1 or 2' using errcode='22023'; end if;
  delete from public.poi_queue where id=private.uuid_or_null(command->>'entryId') and "speechId"=sp.id returning "delegateId" into did;
  if did is null or not exists(select 1 from public.attendance where "sessionId"=sid and "delegateId"=did and status<>'Absent') then raise exception 'POI delegate is unavailable' using errcode='22023'; end if;
  insert into public.participation_events(id,conference_id,committee_id,"delegateId","sessionId","resolutionId","categoryId",points,"chairId","createdAt","speechId",classification,"yieldedFrom") values(new_id,conf,cid,did,sid,sp."resolutionId",'poi',points_value,actor,client_time,sp.id,sp.classification,sp."yieldedFrom");
  update public.speeches set "poiCount"="poiCount"+1,revision=revision+1 where id=sp.id;
 when 'voteMode' then
  if not exists(select 1 from public.documents where id=rid and committee_id=cid and status='In Debate') then raise exception 'Open a resolution for debate first' using errcode='22023'; end if;
  delete from public.votes where "resolutionId"=rid; -- Prior ballot choices remain in the immutable audit log.
  update public.documents set "voteMode"=command->>'mode',"voteType"=command->>'voteType',"sessionId"=sid,revision=revision+1 where id=rid;
 else raise exception 'Unknown procedural command' using errcode='22023';
 end case;
 if kind in ('speechStart','speechYield','speechFinish') then
  insert into public.timers(conference_id,committee_id,"sessionId",duration,remaining,"startedAt") values(conf,cid,sid,90,90,null)
  on conflict("sessionId") do update set remaining=timers.duration,"startedAt"=null,revision=timers.revision+1;
 end if;
 if kind not in ('queueAdd','queueOrder','queueRemove','poiAdd','poiOrder','poiAllowance','debateMode') then
  insert into public.audit_log(conference_id,committee_id,"actorId",action,"entityId",mutation_id,details) values(conf,cid,actor,kind,coalesce(sp.id,rid,did,cid),mutation,command);
 end if;
 insert into private.mutation_receipts(id,conference_id,actor_id,payload) values(mutation,conf,actor,payload);
 insert into public.operational_changes(conference_id,committee_id,topic,mutation_id) values(conf,cid,'chair',mutation);
end $$;
revoke all on function private.apply_procedure(uuid,uuid,jsonb,public.conference_role,text,timestamptz) from public,anon;
grant execute on function private.apply_procedure(uuid,uuid,jsonb,public.conference_role,text,timestamptz) to authenticated;
create or replace function public.apply_conference_mutation(conf uuid,mutation uuid,command jsonb,requested_role public.conference_role,expected text,client_time timestamptz)
returns void language plpgsql security invoker set search_path='' as $$ begin
 if command->>'type' in ('currentSession','debateMode','queueAdd','queueOrder','queueRemove','speechStart','speechYield','speechScore','speechFinish','poiAllowance','poiAdd','poiOrder','poiRecognize','voteMode','vetoRules') then
  perform private.apply_procedure(conf,mutation,command,requested_role,expected,client_time);
 else perform private.apply_mutation(conf,mutation,command,requested_role,expected,client_time); end if;
end $$;

-- Every FK needs a supporting leading-column index; keep fresh-table advisor output actionable.
DO $$ declare fk record; begin
 for fk in select c.conrelid::regclass rel, c.conname, string_agg(quote_ident(a.attname),',' order by u.n) cols
 from pg_constraint c cross join lateral unnest(c.conkey) with ordinality u(attnum,n)
 join pg_attribute a on a.attrelid=c.conrelid and a.attnum=u.attnum
 where c.contype='f' and c.connamespace in ('public'::regnamespace,'private'::regnamespace)
 and not exists(select 1 from pg_index i where i.indrelid=c.conrelid and i.indisvalid and array(select k from unnest(i.indkey) with ordinality z(k,n) order by n limit cardinality(c.conkey))=c.conkey and i.indpred is null)
 group by c.conrelid,c.conname loop
 execute format('create index if not exists %I on %s (%s)',left(fk.conname,53)||'_core_idx',fk.rel,fk.cols);
 end loop;
end $$;

create or replace function public.submit_resolution(link_token text, submission uuid, submitter uuid, title text, google_doc_id text,
  file_name text, storage_key text, file_sha256 text, file_size integer)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 link public.submission_links; existing private.resolution_submissions; sid uuid; n integer; doc_code text; committee_code text;
 doc_id uuid := (substr(submission::text,1,24)||'000000000001')::uuid;
 version_id uuid := (substr(submission::text,1,24)||'000000000002')::uuid;
 submitter_country text; request_payload jsonb;
begin
 select * into link from public.submission_links where token = link_token and revoked_at is null;
 if not found then raise exception 'invalid_link' using errcode='P0001'; end if;
 if (submit_resolution.google_doc_id is null) = (storage_key is null) then raise exception 'invalid_source' using errcode='P0001'; end if;
 if submit_resolution.google_doc_id is not null and submit_resolution.google_doc_id !~ '^[A-Za-z0-9_-]{25,100}$' then raise exception 'invalid_google_doc' using errcode='P0001'; end if;
 request_payload := jsonb_build_object('submitter',submitter,'title',trim(title),'googleDocId',google_doc_id,
   'fileName',case when storage_key is null then null else left(file_name,200) end,
   'storageKey',storage_key,'sha256',file_sha256,'size',file_size);
 -- Serialize a submission UUID across committees before acquiring its committee lock.
 perform pg_advisory_xact_lock(hashtextextended('submission:' || submission::text,0));
 -- Serialize submissions per committee (document numbering, duplicate check).
 perform 1 from public.committees where id = link.committee_id for update;
 if not exists(select 1 from public.submission_links where id=link.id and revoked_at is null) then raise exception 'invalid_link' using errcode='P0001'; end if;
 select * into existing from private.resolution_submissions where id = submission;
 if found then
   if existing.link_id <> link.id or existing.conference_id <> link.conference_id or existing.committee_id <> link.committee_id
      or existing.request_payload is distinct from request_payload then
     raise exception 'idempotency_conflict' using errcode='22023';
   end if;
   return jsonb_build_object('status','replayed','code',(select code from public.documents where id = existing.document_id));
 end if;
 select * into existing from private.resolution_submissions s where s.committee_id = link.committee_id
   and (s.google_doc_id = submit_resolution.google_doc_id or s.file_sha256 = submit_resolution.file_sha256) order by s.created_at limit 1;
 if found then
   if not exists(select 1 from public.delegates where id=submitter and committee_id=link.committee_id) then raise exception 'invalid_submitter' using errcode='P0001'; end if;
   insert into private.resolution_submissions(id,conference_id,committee_id,link_id,document_id,google_doc_id,file_sha256,file_size,request_payload)
   values(submission,link.conference_id,link.committee_id,link.id,existing.document_id,submit_resolution.google_doc_id,submit_resolution.file_sha256,submit_resolution.file_size,request_payload);
   return jsonb_build_object('status','duplicate','code',(select code from public.documents where id = existing.document_id),
     'storageKey',(select v."storageKey" from public.document_versions v where v."documentId"=existing.document_id and v.number=1));
 end if;
 if (select count(*) from private.resolution_submissions where link_id = link.id and created_at > now() - interval '10 minutes') >= 20 then
   raise exception 'rate_limited' using errcode='P0001';
 end if;
 select country into submitter_country from public.delegates where id = submitter and committee_id = link.committee_id and conference_id = link.conference_id;
 if submitter_country is null then raise exception 'invalid_submitter' using errcode='P0001'; end if;
 if length(trim(coalesce(title,''))) < 3 or length(title) > 200 then raise exception 'invalid_title' using errcode='P0001'; end if;
 if storage_key is not null and (submit_resolution.file_sha256 is null or coalesce(submit_resolution.file_size, 0) <= 0
     or storage_key not like link.conference_id::text || '/' || link.committee_id::text || '/' || doc_id::text || '/%') then
   raise exception 'invalid_storage_key' using errcode='P0001';
 end if;
 -- The Chair selection is authoritative; legitimate submissions need no active session.
 select "currentSessionId" into sid from public.committees where id=link.committee_id;
 select code into committee_code from public.committees where id = link.committee_id;
 select count(*) + 1 into n from public.documents where committee_id = link.committee_id;
 loop
   doc_code := committee_code || ' / ' || lpad(n::text, 2, '0');
   exit when not exists(select 1 from public.documents where conference_id = link.conference_id and code = doc_code);
   n := n + 1;
 end loop;
 insert into public.documents(id, conference_id, committee_id, "sessionId", "submitterId", code, title, status)
 values (doc_id, link.conference_id, link.committee_id, sid, submitter, doc_code, trim(title), 'Draft');
 insert into public.document_versions(id, conference_id, committee_id, "documentId", number, "fileName", "storageKey", text)
 values (version_id, link.conference_id, link.committee_id, doc_id, 1,
   case when storage_key is null then 'Google Doc' else left(file_name, 200) end, storage_key,
   'Submitted through the ' || committee_code || ' submission link by ' || submitter_country || '.' || chr(10) ||
   case when storage_key is null
     then 'Working document: Google Doc.' || chr(10) || chr(10) || 'The resolution text lives in the Google Doc. Use “Open Google Doc”.'
     else 'Uploaded file (fallback): ' || left(file_name, 200) || ' (' || greatest(1, round(submit_resolution.file_size / 1024.0))::text || ' KB).' || chr(10) || chr(10) || 'Open the submitted file to read it.'
   end);
 insert into public.resolution_links(document_id, conference_id, committee_id, working_doc_id, submitted_at)
 values (doc_id, link.conference_id, link.committee_id, submit_resolution.google_doc_id, now());
 insert into private.resolution_submissions(id, conference_id, committee_id, link_id, document_id, google_doc_id, file_sha256, file_size, request_payload)
 values (submission, link.conference_id, link.committee_id, link.id, doc_id, submit_resolution.google_doc_id, submit_resolution.file_sha256, submit_resolution.file_size, request_payload);
 -- Notifies the committee's Chair through the existing Realtime path.
 insert into public.operational_changes(conference_id, committee_id, topic, mutation_id) values (link.conference_id, link.committee_id, 'documents', submission);
 return jsonb_build_object('status','created','code',doc_code);
end; $$;
insert into supabase_migrations.schema_migrations(version,name,statements) values('20261006023111','chair_procedure',array[$ledger$-- applied from supabase/migrations/20261006023111_chair_procedure.sql (sha256 0675b72b58fcab91bd6260b7e8349eec5c9464ccbd37ae8e6883d4d4077b1ecb)$ledger$]);

